a)
x = 1;
while (x <= 10);
   ++x;
}
b)
for (double y = .1; y != 1.0; y += .1) {
   printf("%f\n", y);
}
c)
switch (n) {
   case 1:
      puts("The number is 1");
   case 2:
      puts("The number is 2");
      break;
   default:
      puts("The number is not 1 or 2");
      break;
}
d) Đoạn mã sau dự định in các giá trị từ 1 đến 10:
n = 1;
while (n < 10) {
  printf("%d ", n++);
}

task.en:
Find the error in each of the following code segments and explain how to correct it:
a)
x = 1;
while (x <= 10);
   ++x;
}
b)
for (double y = .1; y != 1.0; y += .1) {
   printf("%f\n", y);
}
c)
switch (n) {
   case 1:
      puts("The number is 1");
   case 2:
      puts("The number is 2");
      break;
   default:
      puts("The number is not 1 or 2");
      break;
}
d) The following code should print the values 1 to 10:
n = 1;
while (n < 10) {
  printf("%d ", n++);
}

example.code:
#include <iostream>

int main() {
    // do...while ensures at-least-once execution
    int val = 0;
    do {
        val += 5;
    } while (val < 10);
    std::cout << "Final val: " << val << "\n";

    // continue vs break demonstration
    std::cout << "Loop output: ";
    for (int i = 1; i <= 6; ++i) {
        if (i == 3) {
            continue; // Skip printing 3
        }
        if (i == 5) {
            break; // Terminate loop when reaching 5
        }
        std::cout << i << " ";
    }
    std::cout << "\n";
    return 0;
}

#include <iostream>

int main() {
    int counter = 0;
    auto side_effect = [&counter]() -> bool {
        counter++;
        return true;
    };

    // Short-circuit: false && anything -> right side never runs
    if (false && side_effect()) {
        std::cout << "Unreachable\n";
    }
    std::cout << "Counter after &&: " << counter << "\n";

    // Short-circuit: true || anything -> right side never runs
    if (true || side_effect()) {
        std::cout << "Condition met\n";
    }
    std::cout << "Counter after ||: " << counter << "\n";

    // Yoda notation demonstration
    int val = 10;
    if (10 == val) {
        std::cout << "Val is 10\n";
    }
    return 0;
}

#include <iostream>

int main() {
    // Sum odd integers between 1 and 99
    unsigned int sum = 0;
    for (unsigned int count = 1; count <= 99; count += 2) {
        sum += count;
    }
    std::cout << "Sum of odds 1..99: " << sum << "\n";

    // Multi-column printing: 5 integers per line
    for (unsigned int x = 1; x <= 15; ++x) {
        std::cout << x;
        if (x % 5 == 0) {
            std::cout << "\n";
        } else {
            std::cout << "\t";
        }
    }
    return 0;
}
